            let completed = Arc::clone(&completed);
            handles.push(thread::spawn(move || {
                // Wait until the single shared permit becomes available.
                permit.acquire();

                // Critical section: this activation holds the only permit.
                let mut work = 0usize;
                for i in 0..10_000usize {
